import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Divisione fra numeri interi","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/b_aritmetica-e-numeri/bb/bbf.md","filePath":"lezioni/b_aritmetica-e-numeri/bb/bbf.md"}`),a={name:`lezioni/b_aritmetica-e-numeri/bb/bbf.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="divisione-fra-numeri-interi" tabindex="-1">Divisione fra numeri interi <a class="header-anchor" href="#divisione-fra-numeri-interi" aria-label="Permalink to “Divisione fra numeri interi”">​</a></h1><blockquote><p>Al solito userò indifferentemente la parola quoziente e la parola divisione anche se la prima indica il risultato e la seconda indica l&#39;operazione</p></blockquote><p>Per eseguire la divisione dovremo fare l&#39;operazione contraria della moltiplicazione, cioè se nella moltiplicazione ripetevamo il segmento nella divisione dovremo spezzettare il segmento in parti uguali; se ad esempio devo fare</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="blue"><mo stretchy="false">(</mo><mo>+</mo><mn>6</mn><mo stretchy="false">)</mo><mo>:</mo><mo stretchy="false">(</mo><mo>+</mo><mn>3</mn><mo stretchy="false">)</mo><mo>=</mo></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{(+6) : (+3) =} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen" style="color:blue;">(</span><span class="mord" style="color:blue;">+</span><span class="mord" style="color:blue;">6</span><span class="mclose" style="color:blue;">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:blue;">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen" style="color:blue;">(</span><span class="mord" style="color:blue;">+</span><span class="mord" style="color:blue;">3</span><span class="mclose" style="color:blue;">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:blue;">=</span></span></span></span></span></p><p>significa che devo prendere il segmento lungo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>+</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">+6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">6</span></span></span></span> e, dalla stessa parte dove si trova devo spezzarlo in tre parti uguali e considerare la prima</p><p>quindi:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="blue"><mo stretchy="false">(</mo><mo>+</mo><mn>6</mn><mo stretchy="false">)</mo><mo>:</mo><mo stretchy="false">(</mo><mo>+</mo><mn>3</mn><mo stretchy="false">)</mo><mo>=</mo><mo>+</mo><mn>2</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{(+6) : (+3) = +2} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen" style="color:blue;">(</span><span class="mord" style="color:blue;">+</span><span class="mord" style="color:blue;">6</span><span class="mclose" style="color:blue;">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:blue;">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen" style="color:blue;">(</span><span class="mord" style="color:blue;">+</span><span class="mord" style="color:blue;">3</span><span class="mclose" style="color:blue;">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:blue;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord" style="color:blue;">+</span><span class="mord" style="color:blue;">2</span></span></span></span></span></p><blockquote><p>Per i segni varranno le stesse regole del prodotto</p></blockquote><p>Sorge però un problema: finora i numeri sono come dei paracarri su una strada, cioè sono a distanza regolare fra loro ma in mezzo fra un numero e l&#39;altro non c&#39;è niente, quindi la divisione va bene quando cadiamo esattamente su un numero; però è possibile che il risultato della divisione non corrisponda ad un numero ma cada dove numeri non esistono.</p><p>Diremo che la divisione non è un&#39;operazione interna e l&#39;insieme <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Z</mi></mrow><annotation encoding="application/x-tex">Z</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">Z</span></span></span></span> non è chiuso rispetto alla divisione (cioè non posso sempre fare la divisione in <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Z</mi></mrow><annotation encoding="application/x-tex">Z</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">Z</span></span></span></span>).</p><h3 id="esempio" tabindex="-1">Esempio <a class="header-anchor" href="#esempio" aria-label="Permalink to “Esempio”">​</a></h3><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="blue"><mo stretchy="false">(</mo><mo>+</mo><mn>6</mn><mo stretchy="false">)</mo><mo>:</mo><mo stretchy="false">(</mo><mo>+</mo><mn>4</mn><mo stretchy="false">)</mo><mo>=</mo></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{(+6) : (+4) =} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen" style="color:blue;">(</span><span class="mord" style="color:blue;">+</span><span class="mord" style="color:blue;">6</span><span class="mclose" style="color:blue;">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:blue;">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen" style="color:blue;">(</span><span class="mord" style="color:blue;">+</span><span class="mord" style="color:blue;">4</span><span class="mclose" style="color:blue;">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:blue;">=</span></span></span></span></span></p><p>quindi:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="blue"><mo stretchy="false">(</mo><mo>+</mo><mn>6</mn><mo stretchy="false">)</mo><mo>:</mo><mo stretchy="false">(</mo><mo>+</mo><mn>4</mn><mo stretchy="false">)</mo><mo>=</mo><mo>+</mo><mo stretchy="false">?</mo></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{(+6) : (+4) = +?} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen" style="color:blue;">(</span><span class="mord" style="color:blue;">+</span><span class="mord" style="color:blue;">6</span><span class="mclose" style="color:blue;">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:blue;">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen" style="color:blue;">(</span><span class="mord" style="color:blue;">+</span><span class="mord" style="color:blue;">4</span><span class="mclose" style="color:blue;">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:blue;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord" style="color:blue;">+</span><span class="mclose" style="color:blue;">?</span></span></span></span></span></p><p>Ora, per eseguire sempre la divisione abbiamo due strade:</p><ul><li>la prima è quella di adattare la divisione introducendo il resto (come si faceva alle elementari)</li><li>la seconda è di ampliare l&#39;insieme dei numeri riempiendo lo spazio fra un numero e l&#39;altro in modo da poter sempre fare la divisione</li></ul><p>La seconda strada ci porta all&#39;insieme dei numeri razionali <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span>.</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};